def config_value(text: str, key: str) -> str:
    """Return the value for `key` in `name=value` per-line config text.

    Rules:
    - Each line is split at its first "=", so values may contain "=".
    - Whitespace around the name and around the value is stripped.
    - Blank lines, lines starting with "#" (after stripping), and lines
      without "=" are ignored.
    - Key matching is exact and case-sensitive.
    - If the key appears more than once, the last occurrence wins.
    - Returns "" when the key is absent. A key present with an empty
      value also yields "".
    - Pure function: reads no files.
    """
    result = ""
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        name, sep, value = line.partition("=")
        if not sep:
            continue
        if name.strip() == key:
            result = value.strip()
    return result


def test_basic_lookup() -> None:
    assert config_value("a=1\nb=2\nc=3", "b") == "2"


def test_missing_key_returns_empty() -> None:
    assert config_value("a=1\nb=2", "z") == ""


def test_empty_text() -> None:
    assert config_value("", "a") == ""


def test_whitespace_stripped() -> None:
    assert config_value("  name  =  hello world  \n", "name") == "hello world"


def test_value_may_contain_equals() -> None:
    assert config_value("url=http://x/?q=1&r=2", "url") == "http://x/?q=1&r=2"


def test_empty_value() -> None:
    assert config_value("a=\nb=2", "a") == ""


def test_comments_and_blank_lines_skipped() -> None:
    text = "# a=commented\n\n   \n  # b=also\nb=real"
    assert config_value(text, "a") == ""
    assert config_value(text, "b") == "real"


def test_lines_without_equals_ignored() -> None:
    assert config_value("junk\na=1\nmore junk", "a") == "1"
    assert config_value("junk", "junk") == ""


def test_key_is_case_sensitive_and_exact() -> None:
    text = "Key=upper\nkey=lower\nkey2=other"
    assert config_value(text, "Key") == "upper"
    assert config_value(text, "key") == "lower"
    assert config_value(text, "ke") == ""


def test_duplicate_key_last_wins() -> None:
    assert config_value("a=1\nb=2\na=3", "a") == "3"


def test_crlf_line_endings() -> None:
    assert config_value("a=1\r\nb=2\r\n", "b") == "2"


def test_empty_key_not_matched_by_nonempty() -> None:
    assert config_value("=x\na=1", "a") == "1"
